@Component
class ConnectionHolder {

    @PostConstruct
    void openConnection() {
        System.out.println("Otwieram polaczenie..."); // PO wstrzyknieciu zaleznosci
    }

    @PreDestroy
    void closeConnection() {
        System.out.println("Zamykam polaczenie..."); // PRZED zniszczeniem beana
    }
}

@Configuration
class PoolConfig {

    @Bean(initMethod = "start", destroyMethod = "shutdown")
    ExternalStyleConnectionPool pool() {
        return new ExternalStyleConnectionPool(); // klasa "z zewnatrz", bez mozliwosci adnotacji
    }
}
// Kontener sam wywola pool.start() po utworzeniu i pool.shutdown() przy zamknieciu kontekstu
